mapper.select:
SELECT s.id, s.doctor_id, s.schedule_date, s.time_slot, s.total_quota, s.booked_count, s.status, s.create_time, s.update_time, doc.name AS doctor_name, doc.title AS title, dep.name AS department_name FROM schedule s JOIN doctor doc ON doc.id = s.doctor_id LEFT JOIN department dep ON dep.id = doc.department_id WHERE s.doctor_id = #{doctorId}
AND s.schedule_date >= #{startDate}
AND s.schedule_date <= #{endDate}
ORDER BY s.schedule_date ASC, s.time_slot ASC, s.id ASC

SELECT
FROM appointment a JOIN schedule s ON s.id = a.schedule_id JOIN doctor d ON d.id = s.doctor_id JOIN department dep ON dep.id = d.department_id LEFT JOIN prescription p ON p.appointment_id = a.id WHERE s.doctor_id = #{doctorId}
AND (a.patient_name LIKE CONCAT('%', #{keyword}, '%') OR a.patient_phone LIKE CONCAT('%', #{keyword}, '%'))
AND a.status = #{status}
AND s.schedule_date = #{scheduleDate}
ORDER BY s.schedule_date DESC, s.time_slot DESC, a.id DESC
